fn wait(mut f:impl FnMut()->bool){let deadline=Instant::now()+Duration::from_secs(90);while !f(){assert!(Instant::now()<deadline,"new asynchronous integration wait timed out");thread::sleep(Duration::from_millis(10));}}
fn rgba(frame:&UiFrame)->Vec<u8>{frame.bgra().unwrap().chunks_exact(4).flat_map(|p|[p[2],p[1],p[0],p[3]]).collect()}
